                  />
                  <div
                    className="win-titlebar-button win-maximize"
                    onClick={() => setWindows(windows.map(w => 
                      w.id === window.id ? { ...w, maximized: !w.maximized } : w
                    ))}
                  />
                  <div
                    className="win-titlebar-button win-close"
                    onClick={() => closeWindow(window.id)}
                  />
                </div>
              </div>
              <div className="overflow-auto bg-white" style={{ height: 'calc(100% - 32px)' }}>
                {renderAppContent(window.appId)}
              </div>
            </motion.div>
          )
        ))}
      </AnimatePresence>

      {/* Taskbar */}
      <div className="win-taskbar">
        <div className="flex items-center gap-4 px-6">
          <motion.div
            className="w-10 h-10 bg-win-blue rounded flex items-center justify-center cursor-pointer"
