  appId: string;
  x: number;
  y: number;
  width: number;
  height: number;
  minimized: boolean;
  maximized: boolean;
}

const desktopIcons = [
  { id: 'courses', label: 'Cursos de IA', label_pt: 'Cursos de IA', icon: <BookOpen size={40} />, color: '#667eea' },
  { id: 'cv-creator', label: 'Creador de CV', label_pt: 'Criador de CV', icon: <Briefcase size={40} />, color: '#f093fb' },
  { id: 'pdf-converter', label: 'Conversor PDF', label_pt: 'Conversor PDF', icon: <FileText size={40} />, color: '#4facfe' },
  { id: 'file-explorer', label: 'Explorador', label_pt: 'Explorador', icon: <Monitor size={40} />, color: '#43e97b' },
  { id: 'settings', label: 'Configuración', label_pt: 'Configurações', icon: <Settings size={40} />, color: '#fa709a' },
  { id: 'help', label: 'Ayuda', label_pt: 'Ajuda', icon: <HelpCircle size={40} />, color: '#30cfd0' },
];

export default function Desktop() {
  const [windows, setWindows] = useState<Window[]>([]);
  const [lang, setLang] = useState<'es' | 'pt'>('es');
  const [time, setTime] = useState(new Date());
  const [draggingWindow, setDraggingWindow] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const timer = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const openWindow = (icon: any) => {
    const existing = windows.find(w => w.appId === icon.id);
    if (existing) {
      setWindows(windows.map(w => w.id === existing.id ? { ...w, minimized: false } : w));
      return;
    }

    const newWindow: Window = {
      id: `${icon.id}-${Date.now()}`,
      title: lang === 'es' ? icon.label : icon.label_pt,
      appId: icon.id,
      x: 100 + windows.length * 50,
      y: 100 + windows.length * 50,
      width: 900,
      height: 650,
      minimized: false,
      maximized: false,
    };
    setWindows([...windows, newWindow]);
  };

  const closeWindow = (id: string) => {
    setWindows(windows.filter(w => w.id !== id));
  };

  const minimizeWindow = (id: string) => {
    setWindows(windows.map(w => w.id === id ? { ...w, minimized: !w.minimized } : w));
  };

  const handleMouseDown = (e: React.MouseEvent, windowId: string) => {
    const win = windows.find(w => w.id === windowId);
    if (!win || win.maximized) return;

    setDraggingWindow(windowId);
    setDragOffset({
      x: e.clientX - win.x,
      y: e.clientY - win.y,
    });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!draggingWindow) return;

    setWindows(windows.map(w => 
      w.id === draggingWindow 
        ? { ...w, x: e.clientX - dragOffset.x, y: e.clientY - dragOffset.y }
        : w
    ));
  };

  const handleMouseUp = () => {
    setDraggingWindow(null);
  };

  const renderAppContent = (appId: string) => {
    switch (appId) {
      case 'courses':
        return <CourseExplorer lang={lang} />;
      case 'cv-creator':
        return <CVCreator lang={lang} />;
      case 'pdf-converter':
        return <PDFConverter lang={lang} />;
      case 'file-explorer':
        return (
          <div className="p-6">
            <h2 className="text-2xl font-bold mb-4">
              {lang === 'es' ? 'Explorador de Archivos' : 'Explorador de Arquivos'}
            </h2>
            <p className="text-gray-600">
              {lang === 'es' 
                ? 'Gestiona tus documentos y archivos'
