                {window.title}
              </motion.button>
            ))}
          </div>
          <div className="flex items-center gap-4">
            <div className="text-white text-sm">{time.toLocaleTimeString(lang === 'es' ? 'es-ES' : 'pt-BR', { hour: '2-digit', minute: '2-digit' })}</div>
            <motion.button className="px-3 py-1 bg-white/10 rounded text-white text-xs" onClick={() => setLang(lang === 'es' ? 'pt' : 'es')} whileHover={{ scale: 1.05 }}>
